import { precacheAndRoute } from 'workbox-precaching';
import SyncService from './services/SyncService';
import { setAuthToken } from './services/api';
import db from './db/db';

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST);

// Skip /api/ and /auth/ requests to allow Google OAuth and other server-side routes to work
self.addEventListener('fetch', (event) => {
    const url = new URL(event.request.url);
    if (url.pathname.startsWith('/api/') || url.pathname.startsWith('/auth/')) {
        return; // Let the browser handle these normally
    }
});

// Handle background sync
self.addEventListener('sync', (event) => {
    if (event.tag === 'sync-produs') {
        event.waitUntil(handleSync());
    }
});

// Handle periodic sync
self.addEventListener('periodicsync', (event) => {
    if (event.tag === 'sync-produs-periodic') {
        event.waitUntil(handleSync());
    }
});

async function handleSync() {
    // Before syncing, we need to ensure the token is set in the api service
    // We can get the latest token from a special 'auth' table in Dexie
    const authRecord = await db.yjs_state.get('auth:current');
    if (authRecord && authRecord.token) {
        setAuthToken(authRecord.token);
    }
    
    return SyncService.performSync();
}
